# Python Calculator

Here's a simple calculator program in Python that can perform basic arithmetic operations (addition, subtraction, multiplication, division) as well as some advanced operations (exponentiation, modulus, floor division):

```python
def calculator():
    print("Simple Python Calculator")
    print("Operations available:")
    print("1. Addition (+)")
    print("2. Subtraction (-)")
    print("3. Multiplication (*)")
    print("4. Division (/)")
    print("5. Exponentiation (**)")
    print("6. Modulus (%)")
    print("7. Floor Division (//)")
    print("8. Exit")

    while True:
        try:
            # Get user input
            choice = input("Enter operation (1/2/3/4/5/6/7/8): ")

            if choice == '8':
                print("Exiting calculator...")
                break

            if choice not in ('1', '2', '3', '4', '5', '6', '7'):
                print("Invalid input. Please try again.")
                continue

            num1 = float(input("Enter first number: "))
            num2 = float(input("Enter second number: "))

            # Perform calculation
            if choice == '1':
                print(f"Result: {num1} + {num2} = {num1 + num2}")
            elif choice == '2':
                print(f"Result: {num1} - {num2} = {num1 - num2}")
            elif choice == '3':
                print(f"Result: {num1} * {num2} = {num1 * num2}")
            elif choice == '4':
                if num2 == 0:
                    print("Error! Division by zero.")
                else:
                    print(f"Result: {num1} / {num2} = {num1 / num2}")
            elif choice == '5':
                print(f"Result: {num1} ** {num2} = {num1 ** num2}")
            elif choice == '6':
                print(f"Result: {num1} % {num2} = {num1 % num2}")
            elif choice == '7':
                if num2 == 0:
                    print("Error! Division by zero.")
                else:
                    print(f"Result: {num1} // {num2} = {num1 // num2}")

        except ValueError:
            print("Invalid input. Please enter numbers only.")
        except Exception as e:
            print(f"An error occurred: {e}")

# Run the calculator
if __name__ == "__main__":
    calculator()
```

## Features:
1. Performs basic arithmetic operations (+, -, *, /)
2. Includes advanced operations (exponentiation, modulus, floor division)
3. Handles division by zero errors
4. Validates user input
5. Has a clean exit option

## How to Use:
1. Run the program
2. Select an operation by entering the corresponding number
3. Enter two numbers when prompted
4. See the result
5. Continue calculating or exit

## Alternative Version (with operator symbols):

If you prefer to enter the operator symbols directly instead of numbers, here's a modified version:

```python
def calculator_symbols():
    print("Simple Python Calculator")
    print("Enter 'quit' to exit")

    while True:
        try:
            # Get user input
            expression = input("Enter calculation (e.g., 2 + 3): ")

            if expression.lower() == 'quit':
                print("Exiting calculator...")
                break

            # Split the input into components
            parts = expression.split()
            if len(parts) != 3:
                print("Invalid input format. Please use: number operator number")
                continue

            num1, operator, num2 = parts
            num1 = float(num1)
            num2 = float(num2)

            # Perform calculation
            if operator == '+':
                print(f"Result: {num1} + {num2} = {num1 + num2}")
            elif operator == '-':
                print(f"Result: {num1} - {num2} = {num1 - num2}")
            elif operator == '*':
                print(f"Result: {num1} * {num2} = {num1 * num2}")
            elif operator == '/':
                if num2 == 0:
                    print("Error! Division by zero.")
                else:
                    print(f"Result: {num1} / {num2} = {num1 / num2}")
            elif operator == '**':
                print(f"Result: {num1} ** {num2} = {num1 ** num2}")
            elif operator == '%':
                print(f"Result: {num1} % {num2} = {num1 % num2}")
            elif operator == '//':
                if num2 == 0:
                    print("Error! Division by zero.")
                else:
                    print(f"Result: {num1} // {num2} = {num1 // num2}")
            else:
                print("Invalid operator. Please use +, -, *, /, **, %, or //")

        except ValueError:
            print("Invalid input. Please enter numbers only.")
        except Exception as e:
            print(f"An error occurred: {e}")

# Run the calculator
if __name__ == "__main__":
    calculator_symbols()
```

You can choose either version based on your preference for input style.

